settings.css:
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@600;700&family=Poppins:wght@400;500;600;700&display=swap');

#sn-trial-thank-you-page {
  --sn-ty-coral: #f43357;
  --sn-ty-coral-dark: #b51f3a;
  --sn-ty-navy: #1f293b;
  --sn-ty-ink: #273244;
  --sn-ty-muted: #5f6f82;
  --sn-ty-cream: #faf7f4;
  --sn-ty-blush: #f9ecef;
  --sn-ty-line: #eadde0;
  --sn-ty-white: #ffffff;
  --sn-ty-font-body: 'Poppins', Arial, sans-serif;
  --sn-ty-font-head: 'Playfair Display', Georgia, serif;
  --sn-ty-focus: 0 0 0 4px rgba(244, 51, 87, 0.2);

  position: relative;
  width: 100vw;
  min-height: 100vh;
  margin-inline: calc(50% - 50vw);
  overflow: hidden;
  background: var(--sn-ty-white);
  color: var(--sn-ty-ink);
  font-family: var(--sn-ty-font-body);
  font-size: 16px;
  line-height: 1.65;
  isolation: isolate;
}

#sn-trial-thank-you-page *,
#sn-trial-thank-you-page *::before,
#sn-trial-thank-you-page *::after {
  box-sizing: border-box;
}

#sn-trial-thank-you-page a {
  color: inherit;
  text-decoration: none;
}

#sn-trial-thank-you-page p,
#sn-trial-thank-you-page h1,
#sn-trial-thank-you-page h2 {
  margin: 0;
}

#sn-trial-thank-you-page h1,
#sn-trial-thank-you-page h2 {
  color: var(--sn-ty-navy);
  font-family: var(--sn-ty-font-head);
  font-weight: 700;
  letter-spacing: -0.025em;
  line-height: 1.08;
  text-wrap: balance;
}

#sn-trial-thank-you-page .sn-ty-container {
  width: min(100% - 40px, 1160px);
  margin-inline: auto;
}

#sn-trial-thank-you-page .sn-ty-skip {
  position: fixed;
  z-index: 20;
  inset-block-start: 12px;
  inset-inline-start: 12px;
  padding: 10px 16px;
  border-radius: 999px;
  background: var(--sn-ty-navy);
  color: var(--sn-ty-white);
  font-weight: 700;
  transform: translateY(-160%);
  transition: transform 180ms ease-out;
}

#sn-trial-thank-you-page .sn-ty-skip:focus {
  transform: translateY(0);
}

#sn-trial-thank-you-page .sn-ty-header {
  border-block-end: 1px solid var(--sn-ty-line);
  background: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-header-inner {
  display: flex;
  min-height: 92px;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

#sn-trial-thank-you-page .sn-ty-brand {
  display: inline-flex;
  flex-direction: column;
  align-items: flex-start;
  line-height: 1;
}

#sn-trial-thank-you-page .sn-ty-wordmark {
  color: var(--sn-ty-coral-dark);
  font-family: var(--sn-ty-font-head);
  font-size: 2.5rem;
  font-weight: 700;
  letter-spacing: -0.04em;
}

#sn-trial-thank-you-page .sn-ty-brandline {
  margin-block-start: 4px;
  color: var(--sn-ty-coral-dark);
  font-size: 0.85rem;
}

#sn-trial-thank-you-page .sn-ty-header-status {
  display: inline-flex;
  min-height: 40px;
  align-items: center;
  padding-inline: 16px;
  border-radius: 999px;
  background: var(--sn-ty-blush);
  color: var(--sn-ty-coral-dark);
  font-size: 0.85rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-header-status::before {
  width: 8px;
  height: 8px;
  margin-inline-end: 8px;
  border-radius: 50%;
  background: var(--sn-ty-coral-dark);
  content: '';
}

#sn-trial-thank-you-page .sn-ty-hero {
  padding-block: clamp(56px, 8vw, 96px);
  background: var(--sn-ty-cream);
}

#sn-trial-thank-you-page .sn-ty-hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.45fr) minmax(300px, 0.75fr);
  align-items: center;
  gap: clamp(40px, 7vw, 88px);
}

#sn-trial-thank-you-page .sn-ty-kicker {
  display: inline-flex;
  margin-block-end: 20px;
  padding: 8px 14px;
  border-radius: 999px;
  background: var(--sn-ty-coral-dark);
  color: var(--sn-ty-white);
  font-size: 0.82rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-hero h1 {
  max-width: 760px;
  font-size: clamp(3rem, 6vw, 4.8rem);
}

#sn-trial-thank-you-page .sn-ty-lead {
  max-width: 66ch;
  margin-block-start: 24px;
  color: var(--sn-ty-ink);
  font-size: clamp(1.05rem, 1.6vw, 1.22rem);
  text-wrap: pretty;
}

#sn-trial-thank-you-page .sn-ty-hero-button {
  display: inline-flex;
  min-height: 52px;
  margin-block-start: 28px;
  align-items: center;
  justify-content: center;
  padding: 12px 24px;
  border-radius: 999px;
  background: var(--sn-ty-coral-dark);
  color: var(--sn-ty-white);
  font-weight: 700;
  transition: background-color 180ms ease-out, transform 180ms ease-out;
}

#sn-trial-thank-you-page .sn-ty-hero-button:hover {
  transform: translateY(-2px);
}

#sn-trial-thank-you-page .sn-ty-trial-panel {
  padding: 32px;
  border-radius: 20px;
  background: var(--sn-ty-navy);
  color: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-trial-number {
  font-family: var(--sn-ty-font-head);
  font-size: clamp(3rem, 5vw, 3.5rem);
  font-weight: 700;
  line-height: 0.9;
}

#sn-trial-thank-you-page .sn-ty-trial-label {
  margin-block: 8px 16px;
  color: var(--sn-ty-white);
  font-size: 1rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-trial-panel > div p:last-child {
  color: var(--sn-ty-white);
  font-size: 1rem;
}

#sn-trial-thank-you-page .sn-ty-trial-panel > a {
  display: inline-flex;
  margin-block-start: 24px;
  color: var(--sn-ty-white);
  font-weight: 700;
  text-decoration: underline;
  text-decoration-color: var(--sn-ty-coral);
  text-decoration-thickness: 2px;
  text-underline-offset: 5px;
}

#sn-trial-thank-you-page .sn-ty-trial-panel > small {
  display: block;
  margin-block-start: 8px;
  color: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-steps {
  border-block: 1px solid var(--sn-ty-line);
  background: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-steps ol {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin: 0;
  padding: 24px 0;
  list-style: none;
}

#sn-trial-thank-you-page .sn-ty-steps li {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: 12px;
  padding-inline: 24px;
}

#sn-trial-thank-you-page .sn-ty-steps li + li {
  border-inline-start: 1px solid var(--sn-ty-line);
}

#sn-trial-thank-you-page .sn-ty-steps li > span {
  display: grid;
  width: 32px;
  height: 32px;
  flex: 0 0 auto;
  place-items: center;
  border-radius: 50%;
  background: var(--sn-ty-blush);
  color: var(--sn-ty-coral-dark);
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-path-section {
  padding-block: clamp(64px, 9vw, 112px);
}

#sn-trial-thank-you-page .sn-ty-section-heading {
  max-width: 720px;
  margin-inline: auto;
  text-align: center;
}

#sn-trial-thank-you-page .sn-ty-section-heading h2 {
  font-size: clamp(2.25rem, 4.5vw, 3.8rem);
}

#sn-trial-thank-you-page .sn-ty-section-heading p {
  margin-block-start: 16px;
  color: var(--sn-ty-muted);
  font-size: 1.02rem;
}

#sn-trial-thank-you-page .sn-ty-paths {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
  margin-block-start: 40px;
}

#sn-trial-thank-you-page .sn-ty-path {
  display: flex;
  min-width: 0;
  min-height: 248px;
  flex-direction: column;
  align-items: flex-start;
  padding: 28px 24px 24px;
  border: 2px solid var(--sn-ty-line);
  border-radius: 12px;
  background: var(--sn-ty-white);
  text-align: start;
  transition: border-color 180ms ease-out, background-color 180ms ease-out, transform 180ms ease-out;
}

#sn-trial-thank-you-page .sn-ty-path:hover {
  border-color: var(--sn-ty-coral);
  transform: translateY(-3px);
}

#sn-trial-thank-you-page .sn-ty-path:focus-visible,
#sn-trial-thank-you-page .sn-ty-hero-button:focus-visible,
#sn-trial-thank-you-page .sn-ty-button:focus-visible,
#sn-trial-thank-you-page .sn-ty-text-link:focus-visible,
#sn-trial-thank-you-page .sn-ty-brand:focus-visible,
#sn-trial-thank-you-page .sn-ty-trial-panel > a:focus-visible,
#sn-trial-thank-you-page .sn-ty-inline-link:focus-visible,
#sn-trial-thank-you-page .sn-ty-app-actions a:focus-visible,
#sn-trial-thank-you-page .sn-ty-footer a:focus-visible {
  outline: none;
  box-shadow: var(--sn-ty-focus);
}

#sn-trial-thank-you-page .sn-ty-path[aria-current='true'] {
  border-color: var(--sn-ty-coral);
  background: var(--sn-ty-blush);
}

#sn-trial-thank-you-page .sn-ty-age {
  color: var(--sn-ty-coral-dark);
  font-size: 0.82rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-path > strong {
  margin-block-start: 18px;
  color: var(--sn-ty-navy);
  font-family: var(--sn-ty-font-head);
  font-size: 1.65rem;
  line-height: 1.15;
}

#sn-trial-thank-you-page .sn-ty-path-copy {
  margin-block-start: 12px;
  color: var(--sn-ty-muted);
  font-size: 1rem;
}

#sn-trial-thank-you-page .sn-ty-path-action {
  margin-block-start: auto;
  padding-block-start: 24px;
  color: var(--sn-ty-coral-dark);
  font-size: 0.85rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-result {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 32px;
  margin-block-start: 32px;
  padding: 32px;
  border-radius: 20px;
  background: var(--sn-ty-navy);
  color: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-result[hidden] {
  display: none !important;
}

#sn-trial-thank-you-page .sn-ty-result-label {
  margin-block-end: 8px;
  color: var(--sn-ty-white);
  font-size: 0.82rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-result h2 {
  color: var(--sn-ty-white);
  font-size: clamp(1.75rem, 3vw, 2.4rem);
}

#sn-trial-thank-you-page .sn-ty-result h2:focus {
  outline: none;
}

#sn-trial-thank-you-page .sn-ty-result h2 + p {
  margin-block-start: 10px;
  color: var(--sn-ty-white);
}

#sn-trial-thank-you-page .sn-ty-result-actions {
  display: flex;
  min-width: 250px;
  flex-direction: column;
  align-items: stretch;
  gap: 14px;
}

#sn-trial-thank-you-page .sn-ty-button {
  display: inline-flex;
  min-height: 52px;
  align-items: center;
  justify-content: center;
  padding: 12px 22px;
  border-radius: 999px;
  background: var(--sn-ty-coral-dark);
  color: var(--sn-ty-white);
  font-weight: 700;
  text-align: center;
  transition: background-color 180ms ease-out, transform 180ms ease-out;
}

#sn-trial-thank-you-page .sn-ty-button:hover {
  transform: translateY(-2px);
}

#sn-trial-thank-you-page .sn-ty-text-link {
  color: var(--sn-ty-white);
  font-size: 0.85rem;
  font-weight: 600;
  text-align: center;
  text-decoration: underline;
  text-underline-offset: 4px;
}

#sn-trial-thank-you-page .sn-ty-inline-link {
  color: var(--sn-ty-coral-dark);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 3px;
}

#sn-trial-thank-you-page .sn-ty-app {
  padding-block: 0 clamp(64px, 9vw, 112px);
}

#sn-trial-thank-you-page .sn-ty-app-card {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(260px, 0.75fr);
  align-items: center;
  gap: clamp(28px, 5vw, 64px);
  padding: clamp(28px, 5vw, 52px);
  border-radius: 20px;
  background: var(--sn-ty-blush);
}

#sn-trial-thank-you-page .sn-ty-app-label {
  margin-block-end: 10px;
  color: var(--sn-ty-coral-dark);
  font-size: 0.82rem;
  font-weight: 700;
}

#sn-trial-thank-you-page .sn-ty-app-copy h2 {
  font-size: clamp(1.9rem, 3.5vw, 2.8rem);
}

#sn-trial-thank-you-page .sn-ty-app-copy h2 + p {
  max-width: 66ch;
  margin-block-start: 14px;
  color: var(--sn-ty-muted);
}

#sn-trial-thank-you-page .sn-ty-app-actions {
  display: grid;
  gap: 12px;
}

#sn-trial-thank-you-page .sn-ty-app-actions a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 8px;
  transition: transform 180ms ease-out;
}

#sn-trial-thank-you-page .sn-ty-app-actions a:hover {
  transform: translateY(-2px);
}

#sn-trial-thank-you-page .sn-ty-app-actions img {
  display: block;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}

#sn-trial-thank-you-page .sn-ty-app-actions a[data-app-platform='ios'] img {
  width: 180px;
}

#sn-trial-thank-you-page .sn-ty-app-actions a[data-app-platform='android'] img {
  width: 200px;
}

#sn-trial-thank-you-page .sn-ty-footer {
  border-block-start: 1px solid var(--sn-ty-line);
  background: var(--sn-ty-cream);
}

#sn-trial-thank-you-page .sn-ty-footer-inner {
  display: flex;
  min-height: 112px;
  align-items: center;
  justify-content: center;
  gap: 8px;
  text-align: center;
}

#sn-trial-thank-you-page .sn-ty-footer p {
  color: var(--sn-ty-muted);
}

#sn-trial-thank-you-page .sn-ty-footer a {
  color: var(--sn-ty-coral-dark);
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 4px;
}

@media (max-width: 900px) {
  #sn-trial-thank-you-page .sn-ty-hero-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }

  #sn-trial-thank-you-page .sn-ty-trial-panel {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    align-items: center;
    column-gap: 24px;
  }

  #sn-trial-thank-you-page .sn-ty-trial-panel > a,
  #sn-trial-thank-you-page .sn-ty-trial-panel > small {
    grid-column: 2;
  }

  #sn-trial-thank-you-page .sn-ty-paths {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  #sn-trial-thank-you-page .sn-ty-app-card {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  #sn-trial-thank-you-page .sn-ty-container {
    width: min(100% - 32px, 1160px);
  }

  #sn-trial-thank-you-page .sn-ty-header-inner {
    min-height: 80px;
  }

  #sn-trial-thank-you-page .sn-ty-brandline {
    font-size: 0.85rem;
  }

  #sn-trial-thank-you-page .sn-ty-header-status {
    min-height: 36px;
    padding-inline: 12px;
    font-size: 0.85rem;
  }

  #sn-trial-thank-you-page .sn-ty-hero {
    padding-block: 48px;
  }

  #sn-trial-thank-you-page .sn-ty-hero h1 {
    font-size: clamp(2.65rem, 12vw, 3.7rem);
  }

  #sn-trial-thank-you-page .sn-ty-hero-button {
    width: 100%;
  }

  #sn-trial-thank-you-page .sn-ty-trial-panel {
    display: block;
    padding: 28px 24px;
  }

  #sn-trial-thank-you-page .sn-ty-steps ol {
    grid-template-columns: 1fr;
    padding-block: 12px;
  }

  #sn-trial-thank-you-page .sn-ty-steps li {
    padding: 12px 4px;
  }

  #sn-trial-thank-you-page .sn-ty-steps li + li {
    border-block-start: 1px solid var(--sn-ty-line);
    border-inline-start: 0;
  }

  #sn-trial-thank-you-page .sn-ty-path-section {
    padding-block: 64px;
  }

  #sn-trial-thank-you-page .sn-ty-paths {
    grid-template-columns: 1fr;
    margin-block-start: 32px;
  }

  #sn-trial-thank-you-page .sn-ty-path {
    min-height: 214px;
  }

  #sn-trial-thank-you-page .sn-ty-result {
    grid-template-columns: 1fr;
    padding: 28px 24px;
  }

  #sn-trial-thank-you-page .sn-ty-result-actions {
    min-width: 0;
  }

  #sn-trial-thank-you-page .sn-ty-app {
    padding-block-end: 64px;
  }

  #sn-trial-thank-you-page .sn-ty-app-card {
    padding: 28px 24px;
  }

  #sn-trial-thank-you-page .sn-ty-footer-inner {
    flex-direction: column;
    padding-block: 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  #sn-trial-thank-you-page *,
  #sn-trial-thank-you-page *::before,
  #sn-trial-thank-you-page *::after {
    scroll-behavior: auto !important;
    transition-duration: 0.01ms !important;
  }
}

@media (forced-colors: active) {
  #sn-trial-thank-you-page .sn-ty-path,
  #sn-trial-thank-you-page .sn-ty-trial-panel,
  #sn-trial-thank-you-page .sn-ty-result,
  #sn-trial-thank-you-page .sn-ty-button {
    border: 2px solid CanvasText;
  }
}

